export function install(n){Object.assign(n,{player:function(){return window.zqwyPlayer||null},assetUrl:function(n){const t=String(n).split("/").filter(Boolean).map(encodeURIComponent).join("/");return new URL(`../../../${t}`,import.meta.url).href},formatTime:function(n){if(!Number.isFinite(n)||n<0)return"0:00";const t=Math.floor(n);return`${Math.floor(t/60)}:${String(t%60).padStart(2,"0")}`},plural:function(n,t,r,o){const e=n%10,i=n%100;return 1===e&&11!==i?t:e>=2&&e<=4&&(i<12||i>14)?r:o}})}